* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: #1e1e1e;
  color: #eee;
  padding: 16px;
}
header h1 { margin: 0; font-size: 22px; }
.subtitle { margin: 4px 0 16px; color: #aaa; font-size: 13px; }

.controls, .results, .legend {
  background: #2a2a2a;
  padding: 12px;
  border-radius: 6px;
  margin-bottom: 12px;
}
.control-group {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}
.control-group:last-child { margin-bottom: 0; }
.control-group label {
  font-size: 13px;
  display: flex;
  align-items: center;
  gap: 6px;
}
input[type="number"] {
  width: 70px;
  padding: 4px 6px;
  background: #1e1e1e;
  color: #eee;
  border: 1px solid #444;
  border-radius: 4px;
}
button {
  padding: 6px 14px;
  background: #0e639c;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 13px;
}
button:hover { background: #1177bb; }
#solveBtn { background: #16825d; }
#solveBtn:hover { background: #1da77a; }

.results { display: flex; gap: 24px; flex-wrap: wrap; font-size: 13px; }
.results span { font-weight: bold; color: #fff; }

.legend { display: flex; gap: 16px; align-items: center; font-size: 13px; flex-wrap: wrap; }
.swatch {
  display: inline-block;
  width: 16px;
  height: 16px;
  border-radius: 3px;
  margin-right: 4px;
  vertical-align: middle;
  border: 1px solid #555;
}
.swatch.start { background: orange; }
.swatch.dest { background: #2ecc40; }
.swatch.reward { background: #2196f3; }
.swatch.forbidden { background: #e74c3c; }
.swatch.normal { background: #888; }
.swatch.path { background: #ffeb3b; }

.grid-wrapper {
  overflow: auto;
  background: #2a2a2a;
  padding: 12px;
  border-radius: 6px;
}
#grid {
  display: grid;
  gap: 1px;
  background: #444;
  border: 1px solid #444;
  width: max-content;
}
.cell {
  width: 22px;
  height: 22px;
  background: #888;
  position: relative;
}
.cell.start { background: orange; }
.cell.dest { background: #2ecc40; }
.cell.reward { background: #2196f3; }
.cell.forbidden { background: #e74c3c; }
.cell.path::after {
  content: "";
  position: absolute;
  inset: 4px;
  background: #ffeb3b;
  border-radius: 50%;
  opacity: 0.85;
}

// Cell type constants
const CELL = {
  NORMAL: 0,
  FORBIDDEN: 1,
  REWARD: 2,
  START: 3,
  DEST: 4,
};

/**
 * Min-heap priority queue.
 * Items are compared by their `.priority` (lower = higher priority).
 */
class MinHeap {
  constructor() { this.h = []; }
  size() { return this.h.length; }
  push(item) {
    const h = this.h;
    h.push(item);
    let i = h.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (h[p].priority <= h[i].priority) break;
      [h[p], h[i]] = [h[i], h[p]];
      i = p;
    }
  }
  pop() {
    const h = this.h;
    if (h.length === 0) return undefined;
    const top = h[0];
    const last = h.pop();
    if (h.length > 0) {
      h[0] = last;
      let i = 0;
      const n = h.length;
      while (true) {
        const l = i * 2 + 1, r = i * 2 + 2;
        let best = i;
        if (l < n && h[l].priority < h[best].priority) best = l;
        if (r < n && h[r].priority < h[best].priority) best = r;
        if (best === i) break;
        [h[best], h[i]] = [h[i], h[best]];
        i = best;
      }
    }
    return top;
  }
}

function manhattan(ax, ay, bx, by) {
  return Math.abs(ax - bx) + Math.abs(ay - by);
}

/**
 * Reward-aware best-first search.
 * Maximizes:  score = alpha * rewards - beta * (g + h)
 * The priority queue is a min-heap on (-score), so highest score pops first.
 *
 * To bound state space, we keep the best (lowest g, highest r) per cell:
 * a new visit to a cell is only expanded if it has more rewards OR fewer steps
 * than any previously seen visit to that cell.
 *
 * @param {number[][]} grid
 * @param {[number,number]} start [row, col]
 * @param {[number,number]} goal  [row, col]
 * @param {object} opts { alpha, beta, maxExpansions }
 * @returns {{path: [number,number][]|null, rewards: number, expansions: number}}
 */
function solve(grid, start, goal, opts = {}) {
  const alpha = opts.alpha ?? 5;
  const beta = opts.beta ?? 1;
  const maxExpansions = opts.maxExpansions ?? 5000;

  const R = grid.length;
  const C = grid[0].length;

  const isReward = (r, c) => grid[r][c] === CELL.REWARD;
  const isBlocked = (r, c) => grid[r][c] === CELL.FORBIDDEN;

  // best[r][c] = array of pareto-optimal (g, rewards) seen at this cell.
  // Prune duplicates that are dominated.
  const best = Array.from({ length: R }, () =>
    Array.from({ length: C }, () => [])
  );

  const dominated = (r, c, g, rew) => {
    const arr = best[r][c];
    for (const [bg, brew] of arr) {
      if (bg <= g && brew >= rew) return true;
    }
    return false;
  };
  const addPareto = (r, c, g, rew) => {
    const arr = best[r][c];
    for (let i = arr.length - 1; i >= 0; i--) {
      const [bg, brew] = arr[i];
      if (g <= bg && rew >= brew) arr.splice(i, 1);
    }
    arr.push([g, rew]);
  };

  const pq = new MinHeap();

  const r0 = isReward(start[0], start[1]) ? 1 : 0;
  const h0 = manhattan(start[0], start[1], goal[0], goal[1]);
  const score0 = alpha * r0 - beta * (0 + h0);
  pq.push({
    priority: -score0,
    r: start[0], c: start[1],
    g: 0, rew: r0,
    parent: null,
  });
  addPareto(start[0], start[1], 0, r0);

  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
  let expansions = 0;
  let goalNode = null;

  while (pq.size() > 0 && expansions < maxExpansions) {
    const node = pq.pop();
    expansions++;

    if (node.r === goal[0] && node.c === goal[1]) {
      goalNode = node;
      break;
    }

    for (const [dr, dc] of dirs) {
      const nr = node.r + dr;
      const nc = node.c + dc;
      if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
      if (isBlocked(nr, nc)) continue;

      const ng = node.g + 1;
      const nrew = node.rew + (isReward(nr, nc) ? 1 : 0);

      if (dominated(nr, nc, ng, nrew)) continue;
      addPareto(nr, nc, ng, nrew);

      const nh = manhattan(nr, nc, goal[0], goal[1]);
      const nscore = alpha * nrew - beta * (ng + nh);

      pq.push({
        priority: -nscore,
        r: nr, c: nc,
        g: ng, rew: nrew,
        parent: node,
      });
    }
  }

  if (!goalNode) {
    // Fallback: plain A* ignoring rewards, just to reach the goal.
    return fallbackAStar(grid, start, goal, expansions);
  }

  const path = [];
  let cur = goalNode;
  while (cur) {
    path.push([cur.r, cur.c]);
    cur = cur.parent;
  }
  path.reverse();

  return { path, rewards: goalNode.rew, expansions };
}

/** Plain A* on Manhattan distance, ignoring rewards. */
function fallbackAStar(grid, start, goal, prevExpansions) {
  const R = grid.length, C = grid[0].length;
  const isBlocked = (r, c) => grid[r][c] === CELL.FORBIDDEN;
  const isReward = (r, c) => grid[r][c] === CELL.REWARD;

  const gScore = Array.from({ length: R }, () => new Array(C).fill(Infinity));
  const parent = Array.from({ length: R }, () => new Array(C).fill(null));
  gScore[start[0]][start[1]] = 0;

  const pq = new MinHeap();
  pq.push({
    priority: manhattan(start[0], start[1], goal[0], goal[1]),
    r: start[0], c: start[1], g: 0,
  });

  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
  let expansions = 0;
  let found = false;

  while (pq.size() > 0) {
    const node = pq.pop();
    expansions++;
    if (node.g > gScore[node.r][node.c]) continue;
    if (node.r === goal[0] && node.c === goal[1]) { found = true; break; }
    for (const [dr, dc] of dirs) {
      const nr = node.r + dr, nc = node.c + dc;
      if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
      if (isBlocked(nr, nc)) continue;
      const ng = node.g + 1;
      if (ng < gScore[nr][nc]) {
        gScore[nr][nc] = ng;
        parent[nr][nc] = [node.r, node.c];
        pq.push({
          priority: ng + manhattan(nr, nc, goal[0], goal[1]),
          r: nr, c: nc, g: ng,
        });
      }
    }
  }

  if (!found) return { path: null, rewards: 0, expansions: prevExpansions + expansions };

  const path = [];
  let cur = [goal[0], goal[1]];
  while (cur) {
    path.push(cur);
    cur = parent[cur[0]][cur[1]];
  }
  path.reverse();
  let rewards = 0;
  for (const [r, c] of path) if (isReward(r, c)) rewards++;
  return { path, rewards, expansions: prevExpansions + expansions };
}

// UI controller: generates inputs, renders the grid, runs the solver,
// and visualizes the result path.

const $ = (id) => document.getElementById(id);

let state = {
  grid: [],
  start: null,
  dest: null,
  path: null,
};

function generateGrid() {
  const rows = parseInt($("rows").value, 10);
  const cols = parseInt($("cols").value, 10);
  const rewardPct = parseInt($("rewardPct").value, 10) / 100;
  const forbiddenPct = parseInt($("forbiddenPct").value, 10) / 100;

  const grid = Array.from({ length: rows }, () => new Array(cols).fill(CELL.NORMAL));

  // Random start and destination (distinct)
  const start = [randInt(rows), randInt(cols)];
  let dest;
  do {
    dest = [randInt(rows), randInt(cols)];
  } while (dest[0] === start[0] && dest[1] === start[1]);

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if ((r === start[0] && c === start[1]) || (r === dest[0] && c === dest[1])) continue;
      const v = Math.random();
      if (v < forbiddenPct) grid[r][c] = CELL.FORBIDDEN;
      else if (v < forbiddenPct + rewardPct) grid[r][c] = CELL.REWARD;
    }
  }
  grid[start[0]][start[1]] = CELL.START;
  grid[dest[0]][dest[1]] = CELL.DEST;

  state = { grid, start, dest, path: null };
  renderGrid();
  setStatus("generated");
  $("time").textContent = "-";
  $("steps").textContent = "-";
  $("rewards").textContent = "-";
  $("expansions").textContent = "-";
}

function randInt(n) { return Math.floor(Math.random() * n); }

function renderGrid() {
  const { grid, path } = state;
  const rows = grid.length, cols = grid[0].length;
  const gridEl = $("grid");
  gridEl.style.gridTemplateColumns = `repeat(${cols}, 22px)`;
  gridEl.innerHTML = "";

  const pathSet = new Set();
  if (path) {
    for (const [r, c] of path) pathSet.add(`${r},${c}`);
  }

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const cell = document.createElement("div");
      cell.className = "cell";
      const v = grid[r][c];
      if (v === CELL.START) cell.classList.add("start");
      else if (v === CELL.DEST) cell.classList.add("dest");
      else if (v === CELL.REWARD) cell.classList.add("reward");
      else if (v === CELL.FORBIDDEN) cell.classList.add("forbidden");
      if (pathSet.has(`${r},${c}`) && v !== CELL.START && v !== CELL.DEST) {
        cell.classList.add("path");
      }
      cell.title = `(${r},${c})`;
      gridEl.appendChild(cell);
    }
  }
}

function solveCurrent() {
  if (!state.grid.length) {
    setStatus("generate a grid first");
    return;
  }
  const alpha = parseFloat($("alpha").value);
  const beta = parseFloat($("beta").value);
  const maxExpansions = parseInt($("maxExp").value, 10);

  setStatus("solving...");

  // Defer to next frame so the UI can update.
  requestAnimationFrame(() => {
    const t0 = performance.now();
    const result = solve(state.grid, state.start, state.dest, {
      alpha, beta, maxExpansions,
    });
    const t1 = performance.now();

    state.path = result.path;
    renderGrid();

    if (result.path) {
      setStatus("done");
      $("steps").textContent = result.path.length - 1;
      $("rewards").textContent = result.rewards;
    } else {
      setStatus("no path found");
      $("steps").textContent = "-";
      $("rewards").textContent = "-";
    }
    $("time").textContent = (t1 - t0).toFixed(2);
    $("expansions").textContent = result.expansions;
  });
}

function clearPath() {
  state.path = null;
  renderGrid();
  setStatus("path cleared");
}

function setStatus(s) { $("status").textContent = s; }

$("generateBtn").addEventListener("click", generateGrid);
$("solveBtn").addEventListener("click", solveCurrent);
$("clearBtn").addEventListener("click", clearPath);

generateGrid();

