  // Encode (r,c) as a single int for cheap Set membership.
  const key = (r, c) => r * C + c;

  // Priority for heap ordering. Lower = pops first.  We minimize
  // -(alpha * rewards - beta * h) so reward-rich and goal-near nodes pop
  // first.  `g` is intentionally NOT in the priority -- we don't care
  // about long detours.
  const orderPriority = (rew, h) => -(alpha * rew - beta * h);

  const pq = new MinHeap();

  const r0 = isReward(start[0], start[1]) ? 1 : 0;
  const h0 = manhattan(start[0], start[1], goal[0], goal[1]);
  const startVisited = new Set([key(start[0], start[1])]);
  pq.push({
    priority: orderPriority(r0, h0),
    r: start[0], c: start[1],
    g: 0, rew: r0,
    visited: startVisited,
    parent: null,
  });

  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
  let expansions = 0;
  let goalNode = null;
  // Final score for picking the best goal path: prefer more rewards,
  // break ties by shorter path (so beta still matters at goal time).
  let bestGoalScore = -Infinity;

  while (pq.size() > 0 && expansions < maxExpansions) {
    const node = pq.pop();
    expansions++;

    if (node.r === goal[0] && node.c === goal[1]) {
      const finalScore = alpha * node.rew - beta * node.g;
      if (finalScore > bestGoalScore) {
        bestGoalScore = finalScore;
        goalNode = node;
      }
      continue; // keep searching for a better goal path
    }

    for (const [dr, dc] of dirs) {
      const nr = node.r + dr;
      const nc = node.c + dc;
      if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
      if (isBlocked(nr, nc)) continue;

      const k = key(nr, nc);
      // No revisiting cells already on this path -- each path is simple.
      if (node.visited.has(k)) continue;

      const ng = node.g + 1;
      const nrew = node.rew + (isReward(nr, nc) ? 1 : 0);
      const nh = manhattan(nr, nc, goal[0], goal[1]);

      // Branch-and-bound: optimistic upper bound on what this branch could
      // achieve at the goal.  Assume it still collects every remaining
      // reward in the grid and walks the minimum remaining distance.
      const remainingRewards = totalRewards - nrew;
      const optimisticScore =
        alpha * (nrew + remainingRewards) - beta * (ng + nh);
      if (optimisticScore <= bestGoalScore) continue;

      const newVisited = new Set(node.visited);
      newVisited.add(k);

      pq.push({
        priority: orderPriority(nrew, nh),
        r: nr, c: nc,
        g: ng, rew: nrew,
        visited: newVisited,
        parent: node,
      });
    }
  }

  if (!goalNode) {
    return fallbackAStar(grid, start, goal, expansions);
  }

  const path = [];
  let cur = goalNode;
  while (cur) {
    path.push([cur.r, cur.c]);
    cur = cur.parent;
  }
  path.reverse();

  return { path, rewards: goalNode.rew, expansions };
}"}

